<script setup>
import {computed,ref,watch} from 'vue';
import RaceRunner from './RaceRunner.vue';
const props=defineProps({race:Object,clusters:Array,money:Function,canViewSales:Boolean,error:String});const period=defineModel('period',{type:String});const emit=defineEmits(['refresh']);
const colors={teena:['#0E7A4F','#34D399','C1'],bindhu:['#0F766E','#2DD4BF','C2'],preethi:['#B45309','#FBBF24','C3'],navya:['#6D28D9','#A78BFA','C4']};
const palette=id=>colors[id]||['#0E7A4F','#34D399',''];
const initials=name=>String(name||'?').split(/\s+/).filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase();
const rankBefore=ref({}),rankNow=computed(()=>Object.fromEntries((props.race?.branches||[]).map((b,i)=>[b.code,i+1])));
watch(()=>props.race,(_,old)=>{if(old)rankBefore.value=Object.fromEntries(old.branches.map((b,i)=>[b.code,i+1]));});
const max=computed(()=>Math.max(1,...(props.race?.branches||[]).map(b=>b.net))),leadingCluster=computed(()=>props.race?.clusters[0]),leadingBranch=computed(()=>props.race?.branches[0]);
const position=row=>10+78*Math.min(1,(row.achievement||0)/100);
const amount=n=>props.canViewSales?props.money(n):'••••';
const clusterBranches=id=>props.clusters.find(c=>c.id===id)?.branches.length||0;
</script>
<template><section class="bcc-panel bcc-gold" id="bcc-race" aria-labelledby="bcc-title-race"><header class="bcc-panel-head"><div><h2 id="bcc-title-race">Sales Race Board</h2><p id="lsrbSub">Live cluster &amp; branch ranking · cluster rank: target achieved % · branch rank: net collections · part-payments included</p></div><div class="bcc-race-actions"><div class="lsrb-ctl" id="lsrbCtl"><span class="lc-live" id="lsrbLive" :class="{off:!!error}"><i></i>LIVE</span><div class="lc-seg" id="lsrbSeg"><button type="button" data-p="today" :class="{on:period==='today'}" :aria-pressed="period==='today'" @click="period='today';emit('refresh')">Today</button><button type="button" data-p="mtd" :class="{on:period==='cycle'}" :aria-pressed="period==='cycle'" @click="period='cycle';emit('refresh')">This Month</button></div><button type="button" class="lc-btn" id="lsrbRefresh" title="Refresh now" @click="emit('refresh')">↻</button></div><slot name="tools"/></div></header><div class="bcc-panel-body" id="bcc-body-race"><section id="lsrb" class="lsrb" aria-label="Sales Race Board"><div class="lsrb-body"><div class="lsrb-card race-card"><div class="lsrb-card-h">🏎️ Cluster Race <span>who leads the network</span></div><div class="lanes" id="lsrbLanes"><div v-for="(row,i) in race?.clusters||[]" :key="row.id" class="lane" :data-c="palette(row.id)[2]"><div class="lane-info" :style="{'--cc':palette(row.id)[0]}"><div class="li-cl">Cluster {{palette(row.id)[2].slice(1)}}</div><div class="li-top"><span class="li-who"><span class="av" :class="{king:i===0&&row.net>0}" :style="{'--s':'24px','--c1':palette(row.id)[0],'--c2':palette(row.id)[1]}"><span>{{initials(row.name)}}</span></span><span class="li-head">{{row.name}}</span></span><span class="li-br">{{clusterBranches(row.id)}} Br</span></div><div class="li-stats"><span><small>Bills</small><b class="lb">{{row.bills}}</b></span><i></i><span><small>New</small><b class="lk">{{row.fresh}}</b></span></div></div><div class="lane-track"><div class="lane-fill" :style="{background:'linear-gradient(90deg,transparent,'+palette(row.id)[1]+')',width:position(row)+'%'}"></div><span class="lane-pct">{{row.achievement==null?'Target unavailable':row.achievement.toFixed(1)+'% achieved'}} · {{amount(row.net)}} / {{amount(row.target)}}</span><div class="finish"></div><div class="runner" :style="{left:position(row)+'%'}"><span class="tag" :style="{background:'linear-gradient(135deg,'+palette(row.id).slice(0,2).join(',')+')'}"><span class="pos" :style="{color:palette(row.id)[0]}">{{i+1}}</span>{{palette(row.id)[2]}}</span><RaceRunner :color="palette(row.id)[0]" :accent="palette(row.id)[1]"/></div></div></div></div><div class="champs"><div class="ch-h">Race Leaders</div><div class="ch-grid"><div class="champ" id="lsrbChC"><div class="ch-tx"><small>Leading Cluster Head</small><b>{{leadingCluster?.net>0?leadingCluster.name:'—'}}</b><span>{{leadingCluster?.net>0?clusterBranches(leadingCluster.id)+' branches':'No submitted sales in this period'}}</span><div v-if="leadingCluster?.net>0" class="ch-pills"><em class="g">#1 Cluster</em><em>{{leadingCluster.achievement==null?'Target unavailable':leadingCluster.achievement.toFixed(1)+'% achieved'}} · {{amount(leadingCluster.net)}} net</em></div></div></div><div class="champ" id="lsrbChB"><div class="ch-tx"><small>Leading Branch</small><b>{{leadingBranch?.net>0?leadingBranch.name:'—'}}</b><span>{{leadingBranch?.net>0?leadingBranch.top+' · top sales':'No submitted sales in this period'}}</span><div v-if="leadingBranch?.net>0" class="ch-pills"><em class="g">#1 Branch</em><em>{{amount(leadingBranch.net)}} net collected</em></div></div></div></div></div></div><div class="lsrb-card"><div class="lsrb-card-h">🏆 Branch Leaderboard <span>(top sales employee) · live positions</span></div><div class="board-hd"><span>#</span><span>Br</span><span>Branch (Top Employee)</span><span>Collected net</span><span>Bills</span><span>New</span><span>In-H</span><span>Move</span></div><div class="board" id="lsrbBoard" :style="{height:Math.max(11,race?.branches.length||0)*33+4+'px'}"><div v-for="(b,i) in race?.branches||[]" :key="b.code" class="row" :class="i<3&&b.net>0?'r'+(i+1):''" :style="{top:i*33+'px'}"><span class="rk">{{i+1}}</span><span class="code" :style="{background:palette(b.cluster)[0]}">{{b.code}}</span><div class="nm"><span class="av" :style="{'--s':'22px','--c1':palette(b.cluster)[0],'--c2':palette(b.cluster)[1]}"><span>{{b.code}}</span></span><div class="nm-t"><div class="nm-l"><b>{{b.name}}</b><em class="te">{{b.top?'('+b.top+')':''}}</em></div><div class="bar"><i :style="{width:100*b.net/max+'%',background:'linear-gradient(90deg,'+palette(b.cluster).slice(0,2).join(',')+')'}"></i></div></div></div><span class="num collected">{{amount(b.net)}}</span><span class="num nb" :class="{z:!b.bills}">{{b.bills}}</span><span class="num nk" :class="{z:!b.fresh}">{{b.fresh}}</span><span class="num ni" :class="{z:!b.existing}">{{b.existing}}</span><span class="mv" :class="rankBefore[b.code]>rankNow[b.code]?'up':'dn'">{{!rankBefore[b.code]||rankBefore[b.code]===rankNow[b.code]?'—':(rankBefore[b.code]>rankNow[b.code]?'▲':'▼')+Math.abs(rankBefore[b.code]-rankNow[b.code])}}</span></div></div><div id="lsrbHigh"><h3>🏅 Hi Ticket Sale <small>Top 6 employees · highest collected on one bill · net · shared bills shown jointly</small></h3><div class="hi-grid"><div v-for="(x,i) in race?.high||[]" :key="x.invoice" class="hi-card"><strong>#{{i+1}}</strong><div><b>{{x.names||'Employee unassigned'}}</b><small>{{x.branch}} · {{x.date}} · {{x.invoice}} · {{amount(x.net)}}</small></div></div></div><p v-if="!race?.high.length">No invoice-linked receipts in this period.</p></div></div></div><div class="lsrb-status" id="lsrbStatus" :class="{err:error}" :role="error?'alert':'status'">{{error|| (race?'Updated · auto-refresh every 5 min':'Loading live bills…')}}</div></section></div></section></template>
